#pragma once

/* Signatures de courrier : outils communs aux Paramètres (éditeur, choix par
 * compte) et à la fenêtre de rédaction (insertion, remplacement).
 *
 * Les signatures sont des sources EDS (evo_core_list_signatures) ; la
 * signature des nouveaux messages est celle de l'identité du compte
 * ("signature_uid" de evo_core_list_accounts : "none", "autogenerated" ou
 * uid). La signature des réponses / transferts et la position par rapport au
 * texte cité sont des préférences de l'interface (Settings.h). */

#include "Settings.h"
#include <cwctype>
#include <string>
#include <utility>

namespace EvolutionWin::Signatures
{
    /* identifiants spéciaux d'EDS */
    inline constexpr wchar_t None[] = L"none";
    inline constexpr wchar_t Autogenerated[] = L"autogenerated";

    /* préférence : signature au-dessus du texte cité (réponses, transferts) */
    inline constexpr wchar_t AboveQuoteKey[] = L"compose.signature-above-quote";

    /* préférence par compte : signature des réponses et transferts ("" =
     * identique aux nouveaux messages, "none", "autogenerated" ou uid) */
    inline winrt::hstring ReplyKey(winrt::hstring const& account_uid)
    {
        return L"signatures.reply." + account_uid;
    }

    /* Signature à utiliser pour un compte.
     * Paramètres :
     *   account : objet JSON du compte (evo_core_list_accounts)
     *   reply   : réponse ou transfert
     * Retourne : "none", "autogenerated" ou uid d'une signature. */
    inline winrt::hstring ForAccount(winrt::Windows::Data::Json::JsonObject const& account, bool reply)
    {
        winrt::hstring uid = account.GetNamedString(L"signature_uid", None);
        if (reply)
        {
            winrt::hstring reply_uid = Settings::Instance().GetString(ReplyKey(account.GetNamedString(L"uid", L"")), L"");
            if (!reply_uid.empty())
                uid = reply_uid;
        }
        return uid.empty() ? winrt::hstring{ None } : uid;
    }

    /* Échappe le texte brut pour le HTML (sauts de ligne en <br>). */
    inline std::wstring EscapeHtml(std::wstring_view text)
    {
        std::wstring out;
        out.reserve(text.size() + 32);

        for (wchar_t c : text)
        {
            switch (c)
            {
            case L'&': out += L"&amp;"; break;
            case L'<': out += L"&lt;"; break;
            case L'>': out += L"&gt;"; break;
            case L'"': out += L"&quot;"; break;
            case L'\r': break;
            case L'\n': out += L"<br>"; break;
            default: out += c; break;
            }
        }

        return out;
    }

    /* Texte brut d'un fragment HTML (balises de bloc et <br> en sauts de
     * ligne, autres balises retirées, entités courantes décodées).
     * Paramètres :
     *   html : fragment HTML
     * Retourne : texte avec des sauts de ligne \n, sans saut final. */
    inline std::wstring HtmlToText(std::wstring_view html)
    {
        static constexpr std::wstring_view line_tags[] = { L"br", L"/div", L"/p", L"/li", L"/tr", L"/h1", L"/h2", L"/h3" };
        static constexpr std::pair<std::wstring_view, wchar_t> entities[] = {
            { L"&amp;", L'&' }, { L"&lt;", L'<' }, { L"&gt;", L'>' }, { L"&quot;", L'"' },
            { L"&#39;", L'\'' }, { L"&nbsp;", L' ' } };
        std::wstring out;
        size_t i = 0;

        while (i < html.size())
        {
            wchar_t c = html[i];
            if (c == L'<')
            {
                size_t end = html.find(L'>', i);
                if (end == std::wstring_view::npos)
                    break;
                std::wstring tag{ html.substr(i + 1, end - i - 1) };
                for (auto& t : tag)
                    t = static_cast<wchar_t>(towlower(t));
                for (auto const& line_tag : line_tags)
                {
                    if (tag.compare(0, line_tag.size(), line_tag) == 0 &&
                        (tag.size() == line_tag.size() || !iswalnum(tag[line_tag.size()])))
                    {
                        out += L'\n';
                        break;
                    }
                }
                i = end + 1;
            }
            else if (c == L'&')
            {
                bool decoded = false;
                for (auto const& [name, value] : entities)
                {
                    if (html.substr(i, name.size()) == name)
                    {
                        out += value;
                        i += name.size();
                        decoded = true;
                        break;
                    }
                }
                if (!decoded)
                {
                    out += c;
                    ++i;
                }
            }
            else
            {
                if (c != L'\r' && c != L'\n')
                    out += c;
                ++i;
            }
        }

        while (!out.empty() && (out.back() == L'\n' || out.back() == L' '))
            out.pop_back();

        return out;
    }

    /* Signature automatique d'une identité : nom, organisation, adresse.
     * Paramètres :
     *   account : objet JSON du compte
     *   html    : true pour du HTML (adresse en lien mailto:), false pour du texte
     * Retourne : contenu de la signature. */
    inline std::wstring Autogenerate(winrt::Windows::Data::Json::JsonObject const& account, bool html)
    {
        std::wstring name{ account.GetNamedString(L"real_name", L"") };
        std::wstring organization{ account.GetNamedString(L"organization", L"") };
        std::wstring address{ account.GetNamedString(L"address", L"") };
        std::wstring out;

        auto add_line = [&](std::wstring const& line)
        {
            if (!out.empty())
                out += html ? L"<br>" : L"\n";
            out += line;
        };

        if (!name.empty())
            add_line(html ? EscapeHtml(name) : name);
        if (!organization.empty())
            add_line(html ? EscapeHtml(organization) : organization);
        if (!address.empty())
            add_line(html ? L"<a href=\"mailto:" + EscapeHtml(address) + L"\">" + EscapeHtml(address) + L"</a>" : address);

        return out;
    }

    /* Éditeur HTML des signatures (WebView2, contenteditable) : messages
     * "ready" ; fonctions evoInit({html}), evoExec({cmd, arg}), evoGetHtml(). */
    inline constexpr wchar_t EditorPage[] =
        L"<!DOCTYPE html><html><head><meta charset=\"utf-8\">"
        L"<style>"
        L"html, body { height: 100%; margin: 0; background: #ffffff; color: #1a1a1a; "
        L"font-family: 'Segoe UI', sans-serif; font-size: 11pt; line-height: 1.45; }"
        L"#editor { box-sizing: border-box; min-height: 100%; padding: 10px 12px; outline: none; word-wrap: break-word; }"
        L"img { max-width: 100%; }"
        L"a { color: #0067c0; }"
        L"</style></head><body>"
        L"<div id=\"editor\" contenteditable=\"true\" spellcheck=\"true\"></div>"
        L"<script>"
        L"const ed = document.getElementById('editor');"
        L"window.evoInit = function(cfg) { ed.innerHTML = cfg.html || ''; };"
        L"window.evoExec = function(cfg) { ed.focus(); document.execCommand(cfg.cmd, false, cfg.arg || null); };"
        L"window.evoGetHtml = function() { return ed.innerHTML; };"
        L"window.chrome.webview.postMessage('ready');"
        L"</script></body></html>";
}
